package com.paytaxihub.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="Trip") public class Trip { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Integer tripId; @ManyToOne @JoinColumn(name="driver_id") private Driver driver; @ManyToOne @JoinColumn(name="commuter_id") private User commuter; @ManyToOne @JoinColumn(name="vehicle_id") private Vehicle vehicle; @ManyToOne @JoinColumn(name="route_id") private Route route; private LocalDateTime startTime,endTime; private BigDecimal startLatitude,startLongitude,endLatitude,endLongitude,distanceKm,fareAmount; @Enumerated(EnumType.STRING) private TripStatus tripStatus; public enum TripStatus{Active,Completed,Cancelled} public Trip(){} public Integer getTripId(){return tripId;} public void setTripId(Integer v){tripId=v;} public Driver getDriver(){return driver;} public void setDriver(Driver v){driver=v;} public User getCommuter(){return commuter;} public void setCommuter(User v){commuter=v;} public Vehicle getVehicle(){return vehicle;} public void setVehicle(Vehicle v){vehicle=v;} public Route getRoute(){return route;} public void setRoute(Route v){route=v;} public LocalDateTime getStartTime(){return startTime;} public void setStartTime(LocalDateTime v){startTime=v;} public LocalDateTime getEndTime(){return endTime;} public void setEndTime(LocalDateTime v){endTime=v;} public BigDecimal getStartLatitude(){return startLatitude;} public void setStartLatitude(BigDecimal v){startLatitude=v;} public BigDecimal getStartLongitude(){return startLongitude;} public void setStartLongitude(BigDecimal v){startLongitude=v;} public BigDecimal getEndLatitude(){return endLatitude;} public void setEndLatitude(BigDecimal v){endLatitude=v;} public BigDecimal getEndLongitude(){return endLongitude;} public void setEndLongitude(BigDecimal v){endLongitude=v;} public BigDecimal getDistanceKm(){return distanceKm;} public void setDistanceKm(BigDecimal v){distanceKm=v;} public BigDecimal getFareAmount(){return fareAmount;} public void setFareAmount(BigDecimal v){fareAmount=v;} public TripStatus getTripStatus(){return tripStatus;} public void setTripStatus(TripStatus v){tripStatus=v;} }
